    """Mark gaps in the outline and in repeated straight strokes with color 2."""
    out = [row[:] for row in grid]
    flat = [v for row in grid for v in row]
    bg = max(set(flat), key=flat.count)
    marks = {v for v in flat if v != bg}
    if len(marks) != 1:
        return out
