    h, w = len(grid), len(grid[0])
    coords = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == mark]
    if not coords:
        return out
    rmin = min(r for r, c in coords)
    rmax = max(r for r, c in coords)
    cmin = min(c for r, c in coords)
    cmax = max(c for r, c in coords)

    # Complete the four edges of the marks' bounding rectangle.
    for c in range(cmin, cmax + 1):
        for r in (rmin, rmax):
            if grid[r][c] == bg:
                out[r][c] = 2
    for r in range(rmin, rmax + 1):
        for c in (cmin, cmax):
            if grid[r][c] == bg:
                out[r][c] = 2

    # Also bridge interrupted interior strokes when at least three marks lie
    # on the same row or column (e.g. a dotted line running through the box).
    for r in range(h):
        cols = [c for c in range(w) if grid[r][c] == mark]
        if len(cols) >= 4:
            for a, b in zip(cols, cols[1:]):
                for c in range(a + 1, b):
                    if grid[r][c] == bg:
                        out[r][c] = 2
    for c in range(w):
        rows = [r for r in range(h) if grid[r][c] == mark]
        if len(rows) >= 4:
            for a, b in zip(rows, rows[1:]):
                for r in range(a + 1, b):
                    if grid[r][c] == bg:
                        out[r][c] = 2
    return out
